#!/usr/bin/env python3
"""
钩子实现规则 R6：函数名命名规范 - 首字母严禁小写，首字母之外的字符严禁大写
- 触发器：文件写入/编辑前
- 目标：名称/标识符
- 执行器：正则表达式验证器
"""
import json
import sys
import re
from pathlib import Path

def is_code_file(file_path):
    """检查文件是否为代码文件"""
    code_extensions = {
        '.py', '.js', '.ts', '.jsx', '.tsx', '.java', '.c', '.cpp', '.cc', '.cxx', '.h', '.hpp',
        '.cs', '.rb', '.go', '.rs', '.php', '.swift', '.kt', '.scala', '.clj', '.cljs',
        '.r', '.m', '.mm', '.pl', '.lua', '.vim', '.sh', '.bash', '.zsh', '.fish',
        '.yaml', '.yml', '.json', '.xml', '.html', '.css', '.scss', '.sass', '.less',
        '.sql', '.dockerfile', '.makefile', '.cmake', '.gradle', '.maven', '.sbt',
        '.groovy', '.dart', '.elm', '.haskell', '.hs', '.ml', '.ocaml', '.fs', '.fsx',
        '.erl', '.ex', '.exs', '.jl', '.nim', '.nims', '.zig', '.v', '.vhdl', '.verilog',
        '.sv', '.tcl', '.asm', '.s', '.proto', '.graphql', '.gql', '.thrift',
    }
    path = Path(file_path)
    return path.suffix.lower() in code_extensions

def is_valid_function_name(name):
    """
    检查函数名是否符合规范：首字母大写，其余字母小写
    返回 True 如果符合规范
    """
    if not name or len(name) == 0:
        return True

    # 首字母必须大写
    if not name[0].isupper():
        return False

    # 首字母之外的字符必须小写
    for char in name[1:]:
        if char.isupper():
            return False

    return True

def check_function_names(content, file_path):
    """
    检查代码中的函数名。
    返回 (合格, 错误信息)
    """
    lines = content.split('\n')
    file_ext = Path(file_path).suffix.lower()

    # 根据文件类型选择函数定义模式
    if file_ext == '.py':
        patterns = [
            (r'^\s*def\s+([a-zA-Z_]\w*)\s*\(', 'Python 函数'),
        ]
    elif file_ext in ('.js', '.ts', '.jsx', '.tsx'):
        patterns = [
            (r'^\s*(?:async\s+)?function\s+([a-zA-Z_$]\w*)\s*\(', 'JavaScript/TypeScript 函数'),
            (r'^\s*(?:async\s+)?([a-zA-Z_$]\w*)\s*:\s*(?:async\s*)?\(', 'JavaScript 对象方法'),
            (r'^\s*(?:async\s+)?([a-zA-Z_$]\w*)\s*\s*{\s*$', 'JavaScript 箭头函数'),
        ]
    elif file_ext == '.java':
        patterns = [
            (r'(?:public|private|protected)?\s+(?:static\s+)?(?:synchronized\s+)?(?:\w+)\s+([a-zA-Z_]\w*)\s*\(', 'Java 方法'),
        ]
    elif file_ext in ('.c', '.cpp', '.cc', '.cxx', '.h', '.hpp'):
        patterns = [
            (r'(?:\w+)\s+([a-zA-Z_]\w*)\s*\([^)]*\)\s*(?:{|;)', 'C/C++ 函数'),
        ]
    elif file_ext == '.go':
        patterns = [
            (r'^\s*func\s+(?:\(.*?\)\s+)?([a-zA-Z_]\w*)\s*\(', 'Go 函数'),
        ]
    elif file_ext == '.rb':
        patterns = [
            (r'^\s*def\s+([a-zA-Z_]\w*)\s*[(\[]', 'Ruby 方法'),
        ]
    elif file_ext == '.php':
        patterns = [
            (r'function\s+([a-zA-Z_]\w*)\s*\(', 'PHP 函数'),
        ]
    else:
        # 通用模式
        patterns = [
            (r'(?:def|function)\s+([a-zA-Z_]\w*)\s*[\(\[]', '通用函数定义'),
        ]

    for line_num, line in enumerate(lines, 1):
        # 跳过注释行
        stripped = line.lstrip()
        if stripped.startswith('#') or stripped.startswith('//'):
            continue

        for pattern, pattern_type in patterns:
            matches = re.finditer(pattern, line)
            for match in matches:
                func_name = match.group(1)

                # 检查函数名规范
                if not is_valid_function_name(func_name):
                    # 解释具体违反的规则
                    if func_name[0].islower():
                        error_detail = f"首字母小写'{func_name[0]}'"
                    else:
                        # 找到第一个大写字母
                        for i, char in enumerate(func_name[1:], 1):
                            if char.isupper():
                                error_detail = f"第 {i+1} 个字符大写'{char}'"
                                break

                    return False, f"第 {line_num} 行：函数名'{func_name}'不符合规范（{error_detail}）。规范要求：首字母大写，其余字母小写"

    return True, None

try:
    input_data = json.load(sys.stdin)

    tool_name = input_data.get('tool_name', '')
    tool_input = input_data.get('tool_input', {})
    file_path = tool_input.get('file_path', '')

    if not file_path or tool_name not in ('Write', 'Edit', 'MultiEdit', 'NotebookEdit'):
        sys.exit(0)

    if not is_code_file(file_path):
        sys.exit(0)

    # 获取待写入的内容
    if tool_name == 'Write':
        content = tool_input.get('content', '')
    elif tool_name == 'Edit':
        content = tool_input.get('new_string', '')
    else:
        sys.exit(0)

    # 检查函数名规范
    is_valid, error_msg = check_function_names(content, file_path)

    if not is_valid:
        # exit code 2 会阻止此操作
        sys.stderr.write(f"规则 R6 违反：{error_msg}。规则 R6：你所输出的代码文件里，针对各个函数名的命名规范是：首字母严禁小写，首字母之外的字符严禁大写\n")
        sys.exit(2)

    sys.exit(0)

except Exception as e:
    sys.exit(0)
